      case typeBool:
        return v != 0;
      case typeSint32:
      case typeSint64:
        return _zigzagDecode(v);
      case typeInt32:
      case typeEnum:
        return _s32(v);
      case typeInt64:
        return v;
      case typeUint32:
        return v & 0xffffffff;
